// Shared types for the question-bank pipeline.
// Describes the fixed, stored, per-JD anchor question bank generated by
// question-generation.ts. Separate from the LiveKit agent's live PROBE
// question menu (code_trace/snippet_eval/query_trace etc. in
// livekit-python-agent/interview/tech/phases.py) which governs only
// live follow-up generation during the interview.

export type BankQuestionType = "conceptual" | "snippet_code" | "snippet_query" | "custom";

export type BankQuestion = {
    id: string;
    skill: string;
    subtopic: string;
    question_type: BankQuestionType;
    question: string;
    level: number;
    source: "generated" | "custom";
    edited: boolean;
};

export type QuestionBank = {
    version: number;
    level: number;
    generatedAt: string;
    questions: BankQuestion[];
};
